"use client";

import dayjs from 'dayjs';

import { useState } from 'react';

import { YearView } from '@mantine/schedule';

const year = dayjs().year();

const recurringEventsData = [
  {
    id: 'yearly-series',
    title: 'Monthly architecture review (series)',
    start: `${year}-01-10 09:00:00`,
    end: `${year}-01-10 10:00:00`,
    color: 'blue',
    recurrence: {
      rrule: 'FREQ=MONTHLY;COUNT=12',
      exdate: [`${year}-11-10 09:00:00`],
    },
  },
  {
    id: 'yearly-series-override',
    title: 'Monthly architecture review (moved in Nov)',
    start: `${year}-11-10 13:00:00`,
    end: `${year}-11-10 14:00:00`,
    color: 'grape',
    recurringEventId: 'yearly-series',
    recurrenceId: `${year}-11-10 09:00:00`,
  },
  {
    id: 'year-one-off',
    title: 'One-off summit',
    start: `${year}-12-01 00:00:00`,
    end: `${year}-12-02 00:00:00`,
    color: 'green',
  },
];

function Demo() {
  const [date, setDate] = useState(`${year}-01-01`);
  return (
    <YearView date={date} onDateChange={setDate} events={recurringEventsData} withWeekNumbers />
  );
}
const RendynExampleComponent = Demo;
export function RendynExample() { return <RendynExampleComponent  />; }

"use client";

import dayjs from 'dayjs';

import { ScheduleEventData, YearView } from '@mantine/schedule';

const thisYear = dayjs().format('YYYY');

const eventDays: [date: string, count: number, color: string][] = [
  [`${thisYear}-01-14`, 1, 'blue'],
  [`${thisYear}-02-03`, 3, 'grape'],
  [`${thisYear}-03-21`, 2, 'green'],
  [`${thisYear}-05-09`, 4, 'orange'],
  [`${thisYear}-07-16`, 2, 'cyan'],
  [`${thisYear}-09-02`, 5, 'red'],
  [`${thisYear}-11-27`, 1, 'violet'],
];

const eventData: ScheduleEventData[] = eventDays.flatMap(([date, count, color]) =>
  Array.from({ length: count }, (_, index) => ({
    id: `${date}-${index}`,
    title: `Event ${index + 1}`,
    start: `${date} ${String(9 + index).padStart(2, '0')}:00:00`,
    end: `${date} ${String(10 + index).padStart(2, '0')}:00:00`,
    color,
  }))
);

function Demo() {
  return (
    <YearView
      date={new Date()}
      events={eventData}
      renderDay={(date, dayEvents) => (
        <>
          {dayjs(date).date()}

          {dayEvents.length > 0 && (
            <div
              style={{
                position: 'absolute',
                bottom: 0,
                insetInlineEnd: 0,
                minWidth: 12,
                height: 12,
                borderRadius: 12,
                fontSize: 9,
                lineHeight: '12px',
                fontWeight: 700,
                textAlign: 'center',
                color: 'var(--mantine-color-white)',
                backgroundColor: `var(--mantine-color-${dayEvents[0].color}-filled)`,
              }}
            >
              {dayEvents.length}
            </div>
          )}
        </>
      )}
    />
  );
}
const RendynExampleComponent = Demo;
export function RendynExample() { return <RendynExampleComponent  />; }

